import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('project-tasks')
DB_PATH = 'projects.db'

@dataclass
class StatusUpdateResult:
    task_id: int
    status: str
    updated: bool

def _archive_if_done(conn, task_id: int, status: str) -> None:
    # Move completed tasks out of the active table into the archive table
    if status != 'done':
        return
    conn.execute('INSERT INTO tasks_archive SELECT * FROM tasks WHERE id = ?', (task_id,))
    conn.execute('DELETE FROM tasks WHERE id = ?', (task_id,))

@mcp.tool()
def update_task_status(task_id: int, status: str) -> StatusUpdateResult:
    now = datetime.now(timezone.utc).isoformat()
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute('UPDATE tasks SET status = ?, updated_at = ? WHERE id = ?', (status, now, task_id))
        updated = cur.rowcount > 0
        if updated:
            _archive_if_done(conn, task_id, status)
        conn.commit()
        return StatusUpdateResult(task_id, status, updated)
    finally:
        conn.close()
